hooks.command:
python3 -I -c 'import hashlib,json,os,subprocess,sys,tempfile
r=os.path.abspath(sys.argv[1] or os.curdir)
while not os.path.isfile(os.path.join(r,".refract/bin/agent-check")) and os.path.dirname(r)!=r:
 r=os.path.dirname(r)
def read(rel):
 p=os.path.join(r,rel)
 try:
  return None if os.path.islink(p) else open(p,"rb").read()
 except OSError:
  return None
verified={}
for rel,digest in json.loads(sys.argv[2]).items():
 data=read(rel)
 if data is None or hashlib.sha256(data).hexdigest()!=digest:
  print(json.dumps({"systemMessage":"refract hook skipped: hook scripts do not match the generated hashes; re-run refract"}))
  sys.exit(0)
 verified[rel]=data
with tempfile.TemporaryDirectory() as private:
 copies={}
 for rel,data in verified.items():
  copies[rel]=os.path.join(private,os.path.basename(rel))
  open(copies[rel],"wb").write(data)
 env=dict(os.environ,REFRACT_ROOT=r,REFRACT_VALIDATOR=copies[".refract/bin/validate"])
 sys.exit(subprocess.call([sys.executable,"-I",copies[".refract/bin/agent-check"],"--format","json"],env=env))' "${CLAUDE_PROJECT_DIR:-$PWD}" '{".refract/bin/agent-check":"42432c2b6290ed7dda3ff96a52c0865b7708d80f08f5808a272970a1e84b015b",".refract/bin/validate":"e7cb7098d8329763f653826f7111c79a3f0293e9adaa07ffab5dca3cae6131d6"}'
